repo.donations.py:
"""Donation records."""


class Donation:
    def __init__(self, donor, pounds):
        self.donor = donor
        self.pounds = pounds

    def __repr__(self):
        return "Donation(%r, %r)" % (self.donor, self.pounds)


ROWS = [('omar', 53), ('mia', 45), ('pia', 10), ('pia', 46), ('noor', 8)]


def load_donations():
    """Yield the stored donations one at a time."""
    for donor, pounds in ROWS:
        yield Donation(donor, pounds)

repo.positions.py:
"""Position windows over donations."""


def pounds_between(donations, low, high):
    """Return the pounds of the donations at positions low to high, both included. Positions start at 1."""
    return [x.pounds for x in donations[low - 1:high - 1]]


def first_poundss(donations, n):
    """Return the pounds of the first n donations."""
    return pounds_between(donations, 1, n)


def describe_donation(donation):
    """Return a one-line description of a donation."""
    return "%s: %s" % (donation.donor, donation.pounds)


def group_by_donor(donations):
    """Return a dict from donor to the list of donations with that donor."""
    groups = {}
    for x in donations:
        groups.setdefault(x.donor, []).append(x)
    return groups
